class Solution {
public:
    string findReplaceString(string s, vector<int>& indices, vector<string>& sources, vector<string>& targets) {
        unordered_map<int, int> idxMap;
        for (int i = 0; i < (int)indices.size(); i++) {
            idxMap[indices[i]] = i;
        }

        string result;
        int n = (int)s.length();
        int i = 0;
        while (i < n) {
            auto it = idxMap.find(i);
            if (it != idxMap.end()) {
                int opIdx = it->second;
                const string& src = sources[opIdx];
                if (s.compare(i, src.length(), src) == 0) {
                    result += targets[opIdx];
                    i += (int)src.length();
                    continue;
                }
            }
            result += s[i];
            i++;
        }
        return result;
    }
};
